      console.error(`¡Alerta! Página ${url} está fuera de línea.`);
      // Notificar a los administradores (correo electrónico, Slack, etc.)
    }

    await browser.close();
  } catch (error) {
    console.error(`Error al comprobar ${url}:`, error);
  }
}

